from pathlib import Path
r=Path('opsagent-ts')
def w(p,s):
 p=r/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf8')
w('tests/fixtures/invoice-provider.ts',r'''// Scripted native-call adapter ONLY for exercising runtime mechanics without a paid API key.
// It is not imported by production code and does not count toward eval success.
import type {Provider} from '../../packages/core/src/llm';
import type {Employee,Call} from '../../packages/core/src/types';
export function invoiceProvider(employee:Employee,source:{id:string;vendor:string;number:string;amount:string;due:string}):Provider{let index=0;const actions:(Call|((state:Record<string,unknown>)=>Call))[]=[{name:'browser_login',args:{system:'portal',credential_handle:employee.connectors.portal.credentialHandle}},{name:'browser_navigate',args:{url:employee.connectors.portal.url+'/'+source.id}},state=>({name:'browser_download',args:{id:element(state,'Download PDF')}}),state=>{const history=state.history as {content:string}[];let file='';for(const frame of history){try{const summary=JSON.parse(frame.content) as {toolResultSummary?:string};if(summary.toolResultSummary){const result=JSON.parse(summary.toolResultSummary) as {data?:{file?:string}};if(result.data?.file)file=result.data.file;}}catch{}}return {name:'pdf_extract',args:{file}};},{name:'browser_login',args:{system:'erp',credential_handle:employee.connectors.erp.credentialHandle}},{name:'browser_navigate',args:{url:employee.connectors.erp.url+'/new'}},state=>({name:'browser_select',args:{id:element(state,'Vendor'),value:source.vendor}}),state=>({name:'browser_type',args:{id:element(state,'Invoice number'),text:source.number}}),state=>({name:'browser_type',args:{id:element(state,'Amount INR'),text:source.amount}}),state=>({name:'browser_type',args:{id:element(state,'Due date'),text:source.due}}),state=>({name:'browser_click',args:{id:element(state,'Create payable')}})];
return {json:async(system)=>{if(system.includes('independent verifier'))return {value:{checks:[{criterion:0,system:'erp',kind:'payable',match:{vendor:source.vendor,number:source.number},expected:{vendor:source.vendor,number:source.number,amount:source.amount,due:source.due},sourcePdf:source.number+'.pdf',absent:false}],reason:'Real fresh-browser comparison proposed by a fixture provider'},tokens:1,cost:0};if(system.includes('procedural lessons'))return {value:{lessons:[]},tokens:1,cost:0};if(system.includes('intent-level plan'))return {value:{steps:['Read source PDF','Create a payable with approval','Independently verify fields']},tokens:1,cost:0};return {value:{outcome:'A matching invoice payable',inputs:[],policies:[{rule:'Approval above threshold',citation:'invoice_processing.md'}],criteria:['The source invoice appears exactly once with matching vendor, number, amount and due date']},tokens:1,cost:0};},turn:async(_system,frames)=>{const state=JSON.parse(frames[0].content) as Record<string,unknown>;const next=actions[index++];return {text:'Deterministic mechanics fixture',call:next?(typeof next==='function'?next(state):next):{name:'finish',args:{summary:'Request fresh verification',claimed_outcome:'Do not trust this actor claim'}},tokens:1,cost:0};}};}
function element(state:Record<string,unknown>,label:string){const observation=state.observation as {elements?:string[]};const found=observation.elements?.find(s=>s.includes('"'+label));if(!found)throw Error('Fixture element unavailable: '+label);return Number(/^\[(\d+)\]/.exec(found)?.[1]);}
''')
w('tests/approval.test.ts',r'''import {it,expect} from 'vitest';
import {query} from '../packages/db/src/index';
import {hash} from '../packages/db/src/security';
import {initialCheckpoint} from '../packages/core/src/types';
import {executeRun} from '../packages/core/src/runtime';
import {loadEmployee,loadRun} from '../packages/core/src/store';
import {invoiceProvider} from './fixtures/invoice-provider';
const org='00000000-0000-4000-8000-000000000001',employeeId='00000000-0000-4000-8000-000000000002';
it('runtime parks exact approval, ends job, restores form and independently verifies resumed submission',async()=>{const employee=await loadEmployee(org,employeeId);const [source]=await query<{id:string;vendor:string;number:string;amount:string;due:string}>('SELECT id,vendor,number,amount,due FROM mock_portal.invoices WHERE amount>50000 ORDER BY date DESC LIMIT 1');await query('DELETE FROM mock_erp.payables WHERE vendor=$1 AND number=$2',[source.vendor,source.number]);const [run]=await query<{id:string}>('INSERT INTO platform.runs(org_id,employee_id,task,status,checkpoint) VALUES($1,$2,$3,$4,$5) RETURNING id',[org,employeeId,'High-value approval mechanics fixture; not measured autonomy','QUEUED',JSON.stringify(initialCheckpoint())]);const provider=invoiceProvider(employee,source);try{await executeRun(org,run.id,provider);expect((await loadRun(org,run.id)).status).toBe('AWAITING_APPROVAL');const [approval]=await query<{id:string;action:{values:{amount:string}};fingerprint:string}>('SELECT * FROM platform.approvals WHERE org_id=$1 AND run_id=$2',[org,run.id]);expect(approval.action.values.amount).toBe(source.amount);expect(approval.fingerprint).toBe(hash(approval.action));expect((await query('SELECT id FROM mock_erp.payables WHERE vendor=$1 AND number=$2',[source.vendor,source.number])).length).toBe(0);await query('UPDATE platform.approvals SET status=$1 WHERE id=$2 AND org_id=$3',['APPROVED',approval.id,org]);await executeRun(org,run.id,provider);const finished=await loadRun(org,run.id);expect(finished.status,JSON.stringify(finished.report)).toBe('COMPLETED');expect(JSON.stringify(finished.report)).toContain('VERIFIED');expect((await query<{status:string}>('SELECT status FROM platform.approvals WHERE id=$1',[approval.id]))[0].status).toBe('EXECUTED');}finally{await query('DELETE FROM mock_erp.payables WHERE vendor=$1 AND number=$2',[source.vendor,source.number]);}},120000);
''')
